package com.telehealth.signaling.websocket;

import com.telehealth.signaling.dto.WebRtcSignalDto;
import com.telehealth.signaling.service.RoomAccessService;
import org.springframework.messaging.handler.annotation.DestinationVariable;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Controller;
import java.security.Principal;

@Controller
public class TelehealthSignalingHandler {

    private final SimpMessagingTemplate messagingTemplate;
    private final RoomAccessService roomAccessService;

    public TelehealthSignalingHandler(SimpMessagingTemplate messagingTemplate, RoomAccessService roomAccessService) {
        this.messagingTemplate = messagingTemplate;
        this.roomAccessService = roomAccessService;
    }

    @MessageMapping("/consultation/{roomId}/signal")
    public void relayVideoSignal(
            @DestinationVariable String roomId,
            @Payload WebRtcSignalDto signal,
            Principal principal) {
        if (!roomAccessService.isAuthorizedParticipant(principal.getName(), roomId)) {
            throw new AccessDeniedException("Caller is not a scheduled participant in consultation room " + roomId);
        }
        messagingTemplate.convertAndSend("/topic/consultation/" + roomId, signal);
    }
}
